import { useEffect, useRef, useState } from "react";

import {
  createAGUILoadingCaptionRotator,
  type AGUILoadingTextsByEvent,
  type EventType,
} from "../..";

export type UseAGUILoadingCaptionOptions<TEvent extends string = EventType> = {
  active: boolean;
  eventType: TEvent | null;
  rotateEvery?: number;
  textsByEvent?: AGUILoadingTextsByEvent<TEvent>;
};

// -----
// React binding for the core caption rotator. The
// deck rules live in core; this only owns the timer.
// eventType is a dependency so a new event redraws
// immediately instead of waiting for the next tick.
// -----
export function useAGUILoadingCaption<TEvent extends string = EventType>({
  active,
  eventType,
  rotateEvery = 1800,
  textsByEvent,
}: UseAGUILoadingCaptionOptions<TEvent>): string {
  const [rotator] = useState(() => createAGUILoadingCaptionRotator<TEvent>());
  const [text, setText] = useState("");

  // -----
  // Read through a ref, not a dependency: an inline
  // textsByEvent={{...}} is a new object every render,
  // which would restart the timer and skip to the next
  // caption on any unrelated re-render.
  // -----
  const textsByEventRef = useRef(textsByEvent);
  useEffect(() => {
    textsByEventRef.current = textsByEvent;
  }, [textsByEvent]);

  useEffect(() => {
    const draw = () => {
      const next = rotator.next(eventType, textsByEventRef.current);
      if (next != null) setText(next);
    };

    draw();
    if (!active) return;
    const id = setInterval(draw, rotateEvery);
    return () => clearInterval(id);
  }, [rotator, active, eventType, rotateEvery]);

  return text;
}

import { useEffect, useState } from "react";

import {
  initialAGUILoadingPresence,
  LINGER_MS,
  presenceOnActiveChange,
  presenceOnLingerElapsed,
  type AGUILoadingPresence,
  type AGUILoadingPresenceOptions,
} from "../..";

// -----
// React binding for the core presence rules. The
// active change is applied during render (not in an
// effect) so the loader never flashes hidden for a
// frame before lingering; only the timeout is an effect.
// -----
export function useAGUILoadingPresence(
  active: boolean,
  { whenDone = "linger", lingerMs = LINGER_MS }: AGUILoadingPresenceOptions = {},
): AGUILoadingPresence {
  const [presence, setPresence] = useState(() => initialAGUILoadingPresence(active));
  const [prevActive, setPrevActive] = useState(active);

  if (active !== prevActive) {
    setPrevActive(active);
    setPresence(presenceOnActiveChange(presence, active, { whenDone, lingerMs }));
  }

  useEffect(() => {
    if (presence !== "lingering") return;
    const id = setTimeout(() => setPresence(presenceOnLingerElapsed), lingerMs);
    return () => clearTimeout(id);
  }, [presence, lingerMs]);

  return presence;
}

// -----
// Framework-free timing and frame math for the
// caption animations. Adapters own the timers and
// markup; everything that decides what to show at
// a given moment lives here.
// -----

// "slide-up": new text comes in from below and moves up.
// "slide-down" / "slide-left" / "slide-right": same idea,
// moving down, left or right.
export type AGUILoadingTextAnimation =
  | "slide-up"
  | "slide-down"
  | "slide-left"
  | "slide-right"
  | "typing"
  | "shuffle";

export const AGUI_LOADING_TEXT_ANIMATIONS = [
  "slide-up",
  "slide-down",
  "slide-left",
  "slide-right",
  "typing",
  "shuffle",
] as const satisfies readonly AGUILoadingTextAnimation[];

// -----
// Typing needs longer on screen than a slide/fade swap
// — a long caption can take over a second just to type
// out at TYPE_CHAR_MS/char, so the default 1800ms slide
// rotation would cut it off mid-type.
// -----
export const TEXT_ANIMATION_ROTATE_MS = {
  "slide-up": 1800,
  "slide-down": 1800,
  "slide-left": 1800,
  "slide-right": 1800,
  typing: 3200,
  shuffle: 2000,
} satisfies Record<AGUILoadingTextAnimation, number>;

// -----
// Slide/fade
// -----
export const SLIDE_DURATION_MS = 320;

// -----
// Typing
// -----
export const TYPE_CHAR_MS = 45;

// -----
// A hard on/off blink (steps, no fade) reads as a real
// terminal caret — an eased opacity looks like a glow.
// Shipped as a string so any adapter can inline it.
// -----
export const CARET_BLINK_ANIMATION_NAME = "agui-loading-caret-blink";
export const CARET_BLINK_ANIMATION = `${CARET_BLINK_ANIMATION_NAME} 1s steps(1) infinite`;
export const CARET_KEYFRAMES = `
@keyframes ${CARET_BLINK_ANIMATION_NAME} {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
`;

// -----
// Shuffle
// -----
export const SHUFFLE_FRAME_MS = 35;
export const SHUFFLE_STAGGER_MS = 30;
export const SHUFFLE_SCRAMBLE_MS = 220;

// -----
// Scramble glyphs come from the caption's own letters
// (deduped, case preserved) instead of a fixed A-Z set
// — so the flicker never shows a character that isn't
// actually part of the word being revealed.
// -----
export function shuffleScramblePool(text: string): string[] {
  const unique = [...new Set(text.replace(/\s/g, "").split(""))];
  return unique.length > 0 ? unique : [" "];
}

// Last character's own lock time — the point everything has settled.
export function shuffleDurationMs(text: string): number {
  return Math.max(text.length - 1, 0) * SHUFFLE_STAGGER_MS + SHUFFLE_SCRAMBLE_MS;
}

// -----
// Each letter scrambles before locking to its real
// character, staggered left to right — the leftmost
// letter starts first and locks first, cascading
// rightward. Letters that haven't started yet are blank.
// -----
export function shuffleFrame(
  text: string,
  elapsedMs: number,
  pool: readonly string[] = shuffleScramblePool(text),
): string[] {
  return text.split("").map((char, index) => {
    if (char === " ") return " ";
    const startAt = index * SHUFFLE_STAGGER_MS;
    const lockAt = startAt + SHUFFLE_SCRAMBLE_MS;
    if (elapsedMs >= lockAt) return char;
    if (elapsedMs >= startAt) return pool[Math.floor(Math.random() * pool.length)]!;
    return " ";
  });
}

import { DEFAULT_LOADING_TEXTS_KEY } from "./agui-loading-captions";
import type { EventType } from "./agui-loading-machine";

// -----
// Any per-event override map (icons, colors, …) —
// same keys as textsByEvent, so it shares the same
// strict-by-default TEvent and "default" fallback.
// TValue is whatever the adapter renders (a ReactNode,
// a Vue component, a class name); core never looks inside.
// -----
export type AGUILoadingByEvent<TValue, TEvent extends string = EventType> = Partial<
  Record<TEvent | typeof DEFAULT_LOADING_TEXTS_KEY, TValue>
>;

// -----
// The event's own entry, else "default", else
// undefined for the adapter's built-in fallback.
// Checks key presence rather than ??, so a caller
// can map an event to null to mean "nothing here"
// instead of it silently falling through.
// -----
export function valueForEventType<TValue, TEvent extends string = EventType>(
  eventType: TEvent | null,
  byEvent: AGUILoadingByEvent<TValue, TEvent> | undefined,
): TValue | undefined {
  if (!byEvent) return undefined;
  if (eventType != null && Object.hasOwn(byEvent, eventType)) return byEvent[eventType];
  if (Object.hasOwn(byEvent, DEFAULT_LOADING_TEXTS_KEY)) {
    return byEvent[DEFAULT_LOADING_TEXTS_KEY];
  }
  return undefined;
}

import type { EventType } from "./agui-loading-machine";
import {
  shuffle,
  textsForEventType,
  type AGUILoadingTextsByEvent,
} from "./agui-loading-captions";

export type AGUILoadingCaptionRotator<TEvent extends string = EventType> = {
  next: (
    eventType: TEvent | null,
    textsByEvent?: AGUILoadingTextsByEvent<TEvent>,
  ) => string | null;
};

// -----
// The deck rules every adapter shares. Adapters
// only own the timer: call next() on each tick
// and on every eventType change, render the result.
// -----
export function createAGUILoadingCaptionRotator<
  TEvent extends string = EventType,
>(): AGUILoadingCaptionRotator<TEvent> {
  let deck: { key: TEvent | null; cards: string[] } | null = null;
  let lastText: string | null = null;

  return {
    next(eventType, textsByEvent) {
      // -----
      // Reshuffle on a new event OR once the current
      // deck runs dry — without the length check, the
      // deck sits at [] forever after its last pop and
      // the caption freezes on the last word.
      // -----
      if (deck == null || deck.key !== eventType || deck.cards.length === 0) {
        const cards = shuffle(textsForEventType(eventType, textsByEvent));
        // -----
        // A fresh deck never repeats the caption that's
        // already on screen. next() pops from the end,
        // so the end is the card that shows first.
        // -----
        const top = cards.length - 1;
        if (cards[top] === lastText && cards.length > 1) {
          const swapIndex = Math.floor(Math.random() * top);
          const swap = cards[top]!;
          cards[top] = cards[swapIndex]!;
          cards[swapIndex] = swap;
        }
        deck = { key: eventType, cards };
      }
      const next = deck.cards.pop() ?? null;
      if (next != null) lastText = next;
      return next;
    },
  };
}

