// -----
// LOADING_TEXTS_BY_EVENT only ever holds real AG-UI
// keys, so a widened, non-AG-UI TEvent key just misses
// it and falls through to overrides/default — the cast
// only relaxes the lookup, not what's actually in the map.
// -----
export function textsForEventType<TEvent extends string>(
  eventType: TEvent | null,
  overrides: AGUILoadingTextsByEvent<TEvent> | undefined,
): readonly string[] {
  const key = eventType ?? DEFAULT_LOADING_TEXTS_KEY;
  // SAFETY: indexing with a TEvent key that isn't a real EventType member
  // just misses this object (returns undefined), which the ?? chain below
  // already handles — the cast only widens the key type, not the values.
  const builtIn = LOADING_TEXTS_BY_EVENT as AGUILoadingTextsByEvent<TEvent> & {
    [DEFAULT_LOADING_TEXTS_KEY]: readonly string[];
  };
  return (
    overrides?.[key] ??
    builtIn[key] ??
    overrides?.[DEFAULT_LOADING_TEXTS_KEY] ??
    builtIn[DEFAULT_LOADING_TEXTS_KEY]
  );
}

export function shuffle(items: readonly string[]): string[] {
  const deck = [...items];
  for (let i = deck.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const swap = deck[i]!;
    deck[i] = deck[j]!;
    deck[j] = swap;
  }
  return deck;
}

import { EventType } from "@ag-ui/core";

// -----
// Pure AG-UI loader state machine. No DOM, no
// fetch, no timers — a (state, event) => state
// reducer that can lift straight into a real
// hook once the model is validated. Everything
// below is real @ag-ui/core event shapes, not a
// simplified stand-in.
// -----

// -----
// Re-exported so adapters import EventType from
// core instead of depending on @ag-ui/core directly.
// -----
export { EventType };

export type AGUILoadingStreamEvent =
  | { type: EventType.RUN_STARTED; runId: string }
  | { type: EventType.TEXT_MESSAGE_START; messageId: string; role: string }
  | { type: EventType.TEXT_MESSAGE_CONTENT; messageId: string; delta: string }
  | { type: EventType.TEXT_MESSAGE_END; messageId: string }
  | { type: EventType.TOOL_CALL_START; toolCallId: string; toolCallName: string }
  | { type: EventType.TOOL_CALL_RESULT; toolCallId: string; content: string }
  | { type: EventType.TOOL_CALL_END; toolCallId: string }
  | { type: EventType.RUN_FINISHED; runId: string }
  | { type: EventType.RUN_ERROR; message: string; code?: string };

export type LoadingStatus = "idle" | "running" | "done" | "failed";

export type LoadingMessage = {
  role: string;
  text: string;
  done: boolean;
};

export type LoadingToolCall = {
  toolCallName: string;
  result: string | null;
};

export type AGUILoadingState = {
  status: LoadingStatus;
  runId: string | null;
  lastEventType: EventType | null;
  messages: Record<string, LoadingMessage>;
  messageOrder: string[];
  toolCalls: Record<string, LoadingToolCall>;
  toolCallOrder: string[];
  error: { message: string; code?: string } | null;
};

export const initialAGUILoadingState: AGUILoadingState = {
  status: "idle",
  runId: null,
  lastEventType: null,
  messages: {},
  messageOrder: [],
  toolCalls: {},
  toolCallOrder: [],
  error: null,
};

// -----
// A run that has finished or errored is over —
// the protocol has nothing left to say. Late
// events (a straggling delta, a retried tool
// call) are dropped instead of reopening state,
// which is the bug the original hook had: its
// "delta" case set status back to "loading"
// unconditionally, no matter what came before.
// -----
function isTerminal(state: AGUILoadingState): boolean {
  return state.status === "done" || state.status === "failed";
}

export function aguiLoadingReducer(
  state: AGUILoadingState,
  event: AGUILoadingStreamEvent,
): AGUILoadingState {
  if (isTerminal(state)) return state;

  switch (event.type) {
    case EventType.RUN_STARTED:
      return {
        ...initialAGUILoadingState,
        status: "running",
        runId: event.runId,
        lastEventType: event.type,
      };

    case EventType.TEXT_MESSAGE_START: {
      if (state.messages[event.messageId]) {
        return { ...state, lastEventType: event.type };
      }
      return {
        ...state,
        lastEventType: event.type,
        messages: {
          ...state.messages,
          [event.messageId]: { role: event.role, text: "", done: false },
        },
        messageOrder: [...state.messageOrder, event.messageId],
      };
    }

    case EventType.TEXT_MESSAGE_CONTENT: {
      // -----
      // Every messageId gets its own buffer. The
      // original hook locked onto whichever message
      // first streamed a `{` and silently dropped
      // deltas for any other id — a preamble message
      // plus the structured answer in the same run
      // would lose one of them.
      // -----
      const existing = state.messages[event.messageId] ?? {
        role: "assistant",
        text: "",
        done: false,
      };
      if (existing.done) return { ...state, lastEventType: event.type };
      return {
        ...state,
        lastEventType: event.type,
        messages: {
          ...state.messages,
          [event.messageId]: { ...existing, text: existing.text + event.delta },
        },
        messageOrder: state.messageOrder.includes(event.messageId)
          ? state.messageOrder
          : [...state.messageOrder, event.messageId],
      };
    }

    case EventType.TEXT_MESSAGE_END: {
      const existing = state.messages[event.messageId];
      if (!existing) return { ...state, lastEventType: event.type };
      return {
        ...state,
        lastEventType: event.type,
        messages: {
          ...state.messages,
          [event.messageId]: { ...existing, done: true },
        },
      };
    }

    case EventType.TOOL_CALL_START: {
      // -----
      // Additive by toolCallId. The original hook
      // reset its whole communications[] list on every
      // TOOL_CALL_START, so a second tool call in the
      // same run wiped out the first call's result.
      // -----
      return {
        ...state,
        lastEventType: event.type,
        toolCalls: {
          ...state.toolCalls,
          [event.toolCallId]: { toolCallName: event.toolCallName, result: null },
        },
        toolCallOrder: state.toolCallOrder.includes(event.toolCallId)
          ? state.toolCallOrder
          : [...state.toolCallOrder, event.toolCallId],
      };
    }

    case EventType.TOOL_CALL_RESULT: {
      const existing = state.toolCalls[event.toolCallId];
      return {
        ...state,
        lastEventType: event.type,
        toolCalls: {
          ...state.toolCalls,
          [event.toolCallId]: {
            toolCallName: existing?.toolCallName ?? "unknown",
            result: event.content,
          },
        },
        toolCallOrder: state.toolCallOrder.includes(event.toolCallId)
          ? state.toolCallOrder
          : [...state.toolCallOrder, event.toolCallId],
      };
    }

    case EventType.TOOL_CALL_END:
      return { ...state, lastEventType: event.type };

    case EventType.RUN_FINISHED:
      // -----
      // Completion is the protocol's own signal, not a
      // regex scraped off accumulated JSON text.
      // -----
      return { ...state, status: "done", lastEventType: event.type };

    case EventType.RUN_ERROR:
      // -----
      // The bug this exists to fix: the original hook
      // had no RUN_ERROR branch at all, so a mid-stream
      // error left status stuck on "loading" forever.
      // -----
      return {
        ...state,
        status: "failed",
        lastEventType: event.type,
        error: { message: event.message, code: event.code },
      };

    default:
      return state;
  }
}

// -----
// Whether the loader is on screen. What happens when
// a run ends is set by whenDone:
//   "hide"   — gone on the same render
//   "linger" — stays lingerMs on its final caption
//              ("Wrapping up", or the RUN_ERROR one),
//              then hides. Adapters own the timeout.
//   "keep"   — stays on its final caption until the
//              next run replaces it
// -----

export type AGUILoadingPresence = "hidden" | "running" | "lingering" | "done";

export type AGUILoadingWhenDone = "hide" | "linger" | "keep";

export const LINGER_MS = 1200;

export type AGUILoadingPresenceOptions = {
  whenDone?: AGUILoadingWhenDone;
  // Only read when whenDone is "linger". 0 hides immediately.
  lingerMs?: number;
};

export function initialAGUILoadingPresence(active: boolean): AGUILoadingPresence {
  return active ? "running" : "hidden";
}

// Only a loader that was actually showing lingers or stays —
// one that was never running has nothing to wind down from.
export function presenceOnActiveChange(
  presence: AGUILoadingPresence,
  active: boolean,
  { whenDone = "linger", lingerMs = LINGER_MS }: AGUILoadingPresenceOptions = {},
): AGUILoadingPresence {
  if (active) return "running";
  if (presence !== "running") return presence;
  if (whenDone === "keep") return "done";
  if (whenDone === "linger" && lingerMs > 0) return "lingering";
  return "hidden";
}

export function presenceOnLingerElapsed(
  presence: AGUILoadingPresence,
): AGUILoadingPresence {
  return presence === "lingering" ? "hidden" : presence;
}

import { valueForEventType } from "./agui-loading-by-event";
import { DEFAULT_LOADING_TEXTS_KEY, textsForEventType } from "./agui-loading-captions";
import type {
  AGUILoadingStackedState,
  AGUILoadingStackedStep,
  AGUILoadingStackedStepKind,
} from "./agui-loading-stacked-machine";
import { EventType } from "./agui-loading-machine";

// -----
// Every stacked map value is either a plain value or
// a function of the row — e.g. pick an icon or text
// from step.toolCallName. Plain values stay the
// simple case; the function is there when you need it.
// -----
export type AGUILoadingStackedStepValue<TValue> =
  | TValue
  | ((step: AGUILoadingStackedStep) => TValue);

export type AGUILoadingStackedStepTextValue = AGUILoadingStackedStepValue<string>;

// -----
// Keyed by the event that OPENED the row, not its
// latest one — a tool row goes START → ARGS → END →
// RESULT, so keying by the latest event would flip
// its icon and captions mid-row. Only these five open
// rows (RUN_ERROR opens the error row); keying
// anything else is a type error, not a silent miss.
// -----
export type AGUILoadingStackedStartEvent =
  | EventType.RUN_STARTED
  | EventType.TOOL_CALL_START
  | EventType.TEXT_MESSAGE_START
  | EventType.REASONING_START
  | EventType.RUN_ERROR;

export const STACKED_STEP_START_EVENT = {
  run: EventType.RUN_STARTED,
  tool: EventType.TOOL_CALL_START,
  message: EventType.TEXT_MESSAGE_START,
  reasoning: EventType.REASONING_START,
  error: EventType.RUN_ERROR,
} as const satisfies Record<AGUILoadingStackedStepKind, AGUILoadingStackedStartEvent>;

// -----
// The shape of every stacked ...ByEvent prop (busy,
// done, failed; texts and icons): opening events plus
// "default", each a value or a function of the row.
// -----
export type AGUILoadingStackedByEvent<TValue> = Partial<
  Record<
    AGUILoadingStackedStartEvent | typeof DEFAULT_LOADING_TEXTS_KEY,
    AGUILoadingStackedStepValue<TValue>
  >
>;

// -----
// The row's opening-event entry, else "default", else
// undefined — with a function entry already called on
// the row. An explicit null entry comes back as null.
// -----
export function stackedStepValue<TValue>(
  step: AGUILoadingStackedStep,
  byEvent: AGUILoadingStackedByEvent<TValue> | undefined,
): TValue | undefined {
  const entry = valueForEventType(STACKED_STEP_START_EVENT[step.kind], byEvent);
  // SAFETY: values are never functions themselves (text, text lists,
  // React nodes), so a function entry is always the (step) => value form.
  return typeof entry === "function"
    ? (entry as (step: AGUILoadingStackedStep) => TValue)(step)
    : entry;
}

// -----
// Captions for a busy row: your list for its opening
// event (or "default"), else the built-in captions
// for that opening event. Stable for the row's whole
// life, so the caption deck never resets mid-row.
// -----
export function stackedStepBusyTexts(
  step: AGUILoadingStackedStep,
  busyTextsByEvent: AGUILoadingStackedByEvent<readonly string[]> | undefined,
): readonly string[] {
  return (
    stackedStepValue(step, busyTextsByEvent) ??
    textsForEventType(STACKED_STEP_START_EVENT[step.kind], undefined)
  );
}

export const LOADING_STACKED_DONE_TEXTS = {
  [EventType.RUN_STARTED]: "Started",
  [EventType.TOOL_CALL_START]: (step) =>
    step.toolCallName ? `Called ${step.toolCallName}` : "Called a tool",
  [EventType.TEXT_MESSAGE_START]: "Wrote a response",
  [EventType.REASONING_START]: "Thought it through",
  // The error row is always failed; this entry only completes the map.
  [EventType.RUN_ERROR]: "Something went wrong",
} satisfies Record<AGUILoadingStackedStartEvent, AGUILoadingStackedStepTextValue>;

export const LOADING_STACKED_FAILED_TEXTS = {
  [EventType.RUN_STARTED]: "Couldn't start",
  [EventType.TOOL_CALL_START]: (step) =>
    step.toolCallName ? `Stopped calling ${step.toolCallName}` : "Tool call stopped",
  [EventType.TEXT_MESSAGE_START]: "Response cut off",
  [EventType.REASONING_START]: "Stopped thinking",
  [EventType.RUN_ERROR]: (step) => step.errorMessage || "Something went wrong",
} satisfies Record<AGUILoadingStackedStartEvent, AGUILoadingStackedStepTextValue>;

// -----
// Override for the row's opening event, else the
// override's "default", else the built-in text — the
// same order the icon props use. Null for a busy row,
// whose caption rotates instead.
// -----
export function stackedStepSettledText(
  step: AGUILoadingStackedStep,
  overrides?: {
    doneTextsByEvent?: AGUILoadingStackedByEvent<string>;
    failedTextsByEvent?: AGUILoadingStackedByEvent<string>;
  },
): string | null {
  if (step.status === "active") return null;
  const [custom, builtIn] =
    step.status === "done"
      ? [overrides?.doneTextsByEvent, LOADING_STACKED_DONE_TEXTS]
      : [overrides?.failedTextsByEvent, LOADING_STACKED_FAILED_TEXTS];
  const customText = stackedStepValue(step, custom);
  if (customText !== undefined) return customText;
  const builtInText = builtIn[STACKED_STEP_START_EVENT[step.kind]];
  return typeof builtInText === "function" ? builtInText(step) : builtInText;
}

// -----
// The one-line summary a finished stack collapses to
// (whenDone="collapse"), e.g. "Finished · 4 steps".
// -----
export function stackedSummaryText(state: AGUILoadingStackedState): string {
  const count = stackedStepCount(state);
  const steps = `${count} ${count === 1 ? "step" : "steps"}`;
  return state.status === "failed" ? `Stopped · ${steps}` : `Finished · ${steps}`;
}

// Rows of work in the stack. The error row isn't a step of work, so it isn't counted.
export function stackedStepCount(state: AGUILoadingStackedState): number {
  return state.stepOrder.filter((id) => state.steps[id]?.kind !== "error").length;
}

import {
  EventType,
  type AGUILoadingStreamEvent,
  type LoadingStatus,
} from "./agui-loading-machine";

// -----
// Separate reducer for the stacked loader. It reads
// the same AG-UI events as aguiLoadingReducer but keeps
// its own state, so the single-line loader's state and
// tests never change because of this one.
// -----

export type AGUILoadingStackedEvent =
  | AGUILoadingStreamEvent
  | { type: EventType.REASONING_START; messageId: string }
  | { type: EventType.REASONING_MESSAGE_START; messageId: string }
  | { type: EventType.REASONING_MESSAGE_CONTENT; messageId: string; delta: string }
  | { type: EventType.REASONING_MESSAGE_END; messageId: string }
  | { type: EventType.REASONING_END; messageId: string };

// "error" is the row RUN_ERROR adds so the failure is always visible,
// even when every other row had already finished.
export type AGUILoadingStackedStepKind =
  | "run"
  | "tool"
  | "message"
  | "reasoning"
  | "error";

export type AGUILoadingStackedStepStatus = "active" | "done" | "failed";

// -----
// One row per unit of work, not per event — a message
// streams hundreds of CONTENT deltas but stays one row
// that updates in place until TEXT_MESSAGE_END.
// -----
export type AGUILoadingStackedStep = {
  id: string;
  kind: AGUILoadingStackedStepKind;
  status: AGUILoadingStackedStepStatus;
  // Latest event for this step — drives its captions and icon.
  eventType: EventType;
  toolCallName: string | null;
  // Set on the "error" row only — RUN_ERROR's message.
  errorMessage: string | null;
};

export type AGUILoadingStackedState = {
  status: LoadingStatus;
  runId: string | null;
  lastEventType: EventType | null;
  steps: Record<string, AGUILoadingStackedStep>;
  stepOrder: string[];
  error: { message: string; code?: string } | null;
};

export const initialAGUILoadingStackedState: AGUILoadingStackedState = {
  status: "idle",
  runId: null,
  lastEventType: null,
  steps: {},
  stepOrder: [],
  error: null,
};

const RUN_STEP_ID = "run";
const ERROR_STEP_ID = "error";

// Prefixed so a toolCallId and a messageId can never collide.
const toolStepId = (toolCallId: string) => `tool:${toolCallId}`;
const messageStepId = (messageId: string) => `message:${messageId}`;
const reasoningStepId = (messageId: string) => `reasoning:${messageId}`;

function isTerminal(state: AGUILoadingStackedState): boolean {
  return state.status === "done" || state.status === "failed";
}

// -----
// Adds the step if it's new, otherwise updates it in
// place. Any real work starting also completes the
// run's own "getting started" row.
// -----
function upsertStep(
  state: AGUILoadingStackedState,
  id: string,
  kind: AGUILoadingStackedStepKind,
  eventType: EventType,
  patch: Partial<AGUILoadingStackedStep> = {},
): AGUILoadingStackedState {
  const existing = state.steps[id];
  if (existing && existing.status !== "active") {
    return { ...state, lastEventType: eventType };
  }
  const steps = { ...state.steps };
  const runStep = steps[RUN_STEP_ID];
  if (kind !== "run" && runStep?.status === "active") {
    steps[RUN_STEP_ID] = { ...runStep, status: "done" };
  }
  steps[id] = {
    ...(existing ?? { id, kind, status: "active", toolCallName: null, errorMessage: null }),
    eventType,
    ...patch,
  };
  return {
    ...state,
    lastEventType: eventType,
    steps,
    stepOrder: existing ? state.stepOrder : [...state.stepOrder, id],
  };
}

function settleActiveSteps(
  state: AGUILoadingStackedState,
  status: Exclude<AGUILoadingStackedStepStatus, "active">,
): Record<string, AGUILoadingStackedStep> {
  const steps = { ...state.steps };
  for (const id of state.stepOrder) {
    const step = steps[id]!;
    if (step.status === "active") steps[id] = { ...step, status };
  }
  return steps;
}

// -----
// REASONING_START and REASONING_MESSAGE_START may or
// may not share a messageId. When a reasoning event's
// id has no step yet, it joins the reasoning step
// that's already open instead of stacking a second row.
// -----
function reasoningTarget(state: AGUILoadingStackedState, messageId: string): string {
  const id = reasoningStepId(messageId);
  if (state.steps[id]) return id;
  const open = [...state.stepOrder]
    .reverse()
    .find((stepId) => {
      const step = state.steps[stepId]!;
      return step.kind === "reasoning" && step.status === "active";
    });
  return open ?? id;
}

export function aguiLoadingStackedReducer(
  state: AGUILoadingStackedState,
  event: AGUILoadingStackedEvent,
): AGUILoadingStackedState {
  if (isTerminal(state)) return state;

  switch (event.type) {
    case EventType.RUN_STARTED:
      return upsertStep(
        { ...initialAGUILoadingStackedState, status: "running", runId: event.runId },
        RUN_STEP_ID,
        "run",
        event.type,
      );

    case EventType.TOOL_CALL_START:
      return upsertStep(state, toolStepId(event.toolCallId), "tool", event.type, {
        toolCallName: event.toolCallName,
      });

    // A result is what the user waited for, so it completes the row;
    // TOOL_CALL_END alone (args done, result pending) keeps it active.
    case EventType.TOOL_CALL_RESULT:
      return upsertStep(state, toolStepId(event.toolCallId), "tool", event.type, {
        status: "done",
      });

    case EventType.TOOL_CALL_END:
      return upsertStep(state, toolStepId(event.toolCallId), "tool", event.type);

    case EventType.TEXT_MESSAGE_START:
    case EventType.TEXT_MESSAGE_CONTENT:
      return upsertStep(state, messageStepId(event.messageId), "message", event.type);

    case EventType.TEXT_MESSAGE_END:
      return upsertStep(state, messageStepId(event.messageId), "message", event.type, {
        status: "done",
      });

    case EventType.REASONING_START:
    case EventType.REASONING_MESSAGE_START:
    case EventType.REASONING_MESSAGE_CONTENT:
      return upsertStep(state, reasoningTarget(state, event.messageId), "reasoning", event.type);

    case EventType.REASONING_MESSAGE_END:
    case EventType.REASONING_END:
      return upsertStep(state, reasoningTarget(state, event.messageId), "reasoning", event.type, {
        status: "done",
      });

    // Anything still open when the run ends is treated as finished.
    case EventType.RUN_FINISHED:
      return {
        ...state,
        status: "done",
        lastEventType: event.type,
        steps: settleActiveSteps(state, "done"),
      };

    // -----
    // Rows still in progress fail; finished rows stay
    // done. The error also gets its own row — without
    // it, an error arriving after every row finished
    // (a tool returned, then the run failed) would leave
    // a stack that looks like a clean success.
    // -----
    case EventType.RUN_ERROR:
      return {
        ...state,
        status: "failed",
        lastEventType: event.type,
        steps: {
          ...settleActiveSteps(state, "failed"),
          [ERROR_STEP_ID]: {
            id: ERROR_STEP_ID,
            kind: "error",
            status: "failed",
            eventType: event.type,
            toolCallName: null,
            errorMessage: event.message,
          },
        },
        stepOrder: [...state.stepOrder, ERROR_STEP_ID],
        error: { message: event.message, code: event.code },
      };

    default:
      return state;
  }
}

